import{_ as e,c as t,o,b0 as l}from"./chunks/framework.Becqh7-x.js";const p="/linux-dev-docs/assets/image-20230719202714621.DKnoFLa3.png",r="/linux-dev-docs/assets/image-20230719203508088.DANLzsR2.png",b=JSON.parse('{"title":"LV005-ARM处理器怎么运行","description":null,"frontmatter":{"title":"LV005-ARM处理器怎么运行","date":"2026-01-06T14:28:05.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/platform/cortexA7/126d2c6e045502a298b345eb","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T14:28:05.042Z","fulluuid":"298b345eb0ee4b9288043859f5f4074f","useduuid":"298b345eb"}},"headers":[],"relativePath":"sdoc/platform/cortexA7/126d2c6e045502a298b345eb.md","filePath":"sdoc/10-开发平台/10-Cortex-A7/LV005-ARM处理器怎么运行.md","lastUpdated":1768604092000}'),s={name:"sdoc/platform/cortexA7/126d2c6e045502a298b345eb.md"};function n(i,a,c,d,m,u){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="lv005-arm处理器怎么运行" tabindex="-1">LV005-ARM处理器怎么运行 <a class="header-anchor" href="#lv005-arm处理器怎么运行" aria-label="Permalink to &quot;LV005-ARM处理器怎么运行&quot;">​</a></h1><h2 id="一、大概流程" tabindex="-1">一、大概流程 <a class="header-anchor" href="#一、大概流程" aria-label="Permalink to &quot;一、大概流程&quot;">​</a></h2><p>ARM 芯片属于精简指令集计算机(RISC： Reduced Instruction SetComputing)，它所用的指令比较简单，有如下特点：</p><p>（1）对内存只有读、写指令。</p><p>（2）对于数据的运算是在 CPU 内部实现。</p><p>（3）使用 RISC 指令的 CPU 复杂度小一点，易于设计。</p><p>比如对于 a = a + b 这样的算式，需要经过下面 4 个步骤才可以实现：</p><img src="'+p+'" alt="image-20230719202714621" style="zoom:50%;"><h2 id="二、几个问题" tabindex="-1">二、几个问题？ <a class="header-anchor" href="#二、几个问题" aria-label="Permalink to &quot;二、几个问题？&quot;">​</a></h2><p>有下边几个问题：</p><p>（1）读 a，那么 a 的值读出来后保存在 CPU 里面哪里？</p><p>（2）读 b，那么 b 的值读出来后保存在 CPU 里面哪里？</p><p>（3）a+b 的结果又保存在哪里？</p><p>我们需要深入 ARM 处理器的内部。简单概括如下，我们先忽略各种 CPU 模式(系统模式、用户模式等等)。</p><img src="'+r+'" alt="image-20230719203508088" style="zoom:50%;"><p>CPU 运行时，先去取得指令，再执行指令：</p><p>（1）把内存 a 的值读入 CPU 寄存器 R0</p><p>（2）把内存 b 的值读入 CPU 寄存器 R1</p><p>（3）把 R0、 R1 累加，存入 R0</p><p>（4）把 R0 的值写入内存 a</p><p>现在我们大概知道了： CPU 内部有很多寄存器， CPU 要从外部设备上读入指令，执行指令。</p>',21)])])}const f=e(s,[["render",n]]);export{b as __pageData,f as default};
